from typing import List
from collections import Counter, deque

class Solution:
    def watchedVideosByFriends(self, watchedVideos: List[List[str]], friends: List[List[int]], id: int, level: int) -> List[str]:
        n = len(friends)
        dist = [-1] * n
        q = deque([id])
        dist[id] = 0
        while q:
            u = q.popleft()
            if dist[u] == level:
                continue
            for v in friends[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        count = Counter()
        for i in range(n):
            if dist[i] == level:
                count.update(watchedVideos[i])
        return sorted(count, key=lambda s: (count[s], s))

