import java.io.*;
import java.util.*;

class Solution {
    public List<String> watchedVideosByFriends(List<List<String>> watchedVideos, int[][] friends, int id, int level) {
        int n = friends.length;
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(id);
        dist[id] = 0;

        while (!q.isEmpty()) {
            int u = q.poll();
            if (dist[u] == level) continue;
            for (int v : friends[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                }
            }
        }

        Map<String, Integer> count = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            if (dist[i] != level) continue;
            for (String video : watchedVideos.get(i)) {
                count.put(video, count.getOrDefault(video, 0) + 1);
            }
        }

        List<String> result = new ArrayList<>(count.keySet());
        result.sort((a, b) -> {
            int byFreq = Integer.compare(count.get(a), count.get(b));
            return byFreq != 0 ? byFreq : a.compareTo(b);
        });
        return result;
    }
}

