static void expectChar(const string& s, size_t& p, char c) {
    skipWs(s, p);
    if (p >= s.size() || s[p] != c) throw runtime_error("bad json");
    ++p;
}

static string parseString(const string& s, size_t& p) {
    skipWs(s, p);
    expectChar(s, p, '"');
    string out;
    while (p < s.size()) {
        char c = s[p++];
        if (c == '"') break;
        if (c == '\\') {
            if (p >= s.size()) throw runtime_error("bad escape");
            char e = s[p++];
            if (e == '"' || e == '\\' || e == '/') out.push_back(e);
            else if (e == 'n') out.push_back('\n');
            else if (e == 'r') out.push_back('\r');
            else if (e == 't') out.push_back('\t');
            else throw runtime_error("unsupported escape");
        } else out.push_back(c);
    }
    return out;
}

static int parseInt(const string& s, size_t& p) {
    skipWs(s, p);
    int sign = 1;
    if (s[p] == '-') { sign = -1; ++p; }
    int v = 0;
    while (p < s.size() && isdigit(static_cast<unsigned char>(s[p]))) v = v * 10 + (s[p++] - '0');
    return sign * v;
}

static vector<string> parseStringArray(const string& s, size_t& p) {
    vector<string> a;
    expectChar(s, p, '[');
    skipWs(s, p);
    if (p < s.size() && s[p] == ']') { ++p; return a; }
    while (true) {
        a.push_back(parseString(s, p));
        skipWs(s, p);
        if (s[p] == ']') { ++p; break; }
        expectChar(s, p, ',');
    }
    return a;
}

