function watchedVideosByFriends(watchedVideos, friends, id, level) {
    const n = friends.length;
    const dist = Array(n).fill(-1);
    const queue = [id];
    let head = 0;
    dist[id] = 0;

    while (head < queue.length) {
        const u = queue[head++];
        if (dist[u] === level) continue;
        for (const v of friends[u]) {
            if (dist[v] === -1) {
                dist[v] = dist[u] + 1;
                queue.push(v);
            }
        }
    }

    const count = new Map();
    for (let i = 0; i < n; ++i) {
        if (dist[i] !== level) continue;
        for (const video of watchedVideos[i]) {
            count.set(video, (count.get(video) || 0) + 1);
        }
    }

    return [...count.keys()].sort((a, b) => {
        const byFreq = count.get(a) - count.get(b);
        return byFreq !== 0 ? byFreq : a.localeCompare(b);
    });
}

